-- Run this in the Supabase SQL editor (Database > SQL Editor).
-- Safe to re-run: every insert is `on conflict ... do nothing`, so it only
-- ever adds what's missing — it never edits or deletes existing rows.
--
-- Second batch of landmarks after scripts/add_landmarks.sql: 416 more
-- landmarks across 141 countries (the original countries plus new ones), plus any
-- missing cities. Unlike add_landmarks.sql this file does NOT create
-- `catalog_highlights` ("Yeni eklenenler") rows — the home rail only shows
-- the newest 20, so a bulk import would push every curated highlight off
-- it. Highlight individual landmarks later from the admin panel
-- ("Yeni eklenenler" checkbox) or with the snippet at the bottom.
-- Photos are left empty on purpose — upload them from the admin panel.
--
-- To add more, append rows to the `_new_landmarks` values list (keep `ord`
-- increasing and above the current max) and re-run the whole file.
-- `country_id` is the `id` from data/worldCountries.json, not a name lookup.

begin;

create temp table _new_landmarks (
  ord int not null,
  country_id text not null,
  city text not null,
  city_tr text,
  name text not null,
  name_tr text,
  description text,
  description_tr text
) on commit drop;


-- Cities (reuses an existing city with the same English name per country).
select distinct on (country_id, city) country_id, city, city_tr
from _new_landmarks
order by country_id, city, ord
on conflict (country_id, name) do nothing;

-- Landmarks. sort_order follows list order (all above add_landmarks.sql's
-- 1-98), so a city's older landmarks keep showing first.
select n.country_id, c.id, n.name, n.name_tr, n.description, n.description_tr, n.ord
from _new_landmarks n
join public.cities c on c.country_id = n.country_id and c.name = n.city
order by n.ord
on conflict (city_id, name) do nothing;

commit;

